const PREF_STORE='wireless500_prefs_v2', LEGACY_STORE='wireless500_stats_v1';
let prefs={},legacy={};
try{prefs=StudyStore.readLegacy(PREF_STORE)||{}}catch{prefs={}}
try{legacy=StudyStore.readLegacy(LEGACY_STORE)||{}}catch{legacy={}}
const validProgress=v=>v&&typeof v==='object'&&!Array.isArray(v)?v:{};
const currentProgress=validProgress(prefs.progress),legacyProgress=validProgress(legacy.progress);
const data={progress:Object.keys(currentProgress).length?currentProgress:legacyProgress,
 bookmarks:Array.isArray(prefs.bookmarks)?prefs.bookmarks:Array.isArray(legacy.bookmarks)?legacy.bookmarks:[],
 history:Array.isArray(prefs.history)?prefs.history:Array.isArray(legacy.history)?legacy.history:[],
 theme:(prefs.theme||legacy.theme)==='dark'?'dark':'light'};
let session=null,lastSessionIds=[],lastSessionConfig=null,bankPage=0,bankOpened=null,currentView='home';
const $=id=>document.getElementById(id),el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
function save(){StudyStore.writeLegacy(PREF_STORE,{version:3,progress:data.progress,bookmarks:data.bookmarks,history:data.history,theme:data.theme})}
function toast(message){const t=$('toast');t.textContent=message;t.hidden=false;clearTimeout(toast._timer);toast._timer=setTimeout(()=>t.hidden=true,2700)}
function rate(a,b){return b?Math.round(100*a/b):0}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function view(name){for(const id of ['home','quiz','result','bank','records','analytics'])$(id+'View').hidden=id!==name;currentView=name;document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===name));if(name==='home')renderHome();if(name==='bank')renderBank();if(name==='records')renderRecords();if(name==='analytics')StudyUI.render('wireless');window.scrollTo({top:0,behavior:'instant'})}
function chaptersSelect(select,includeAll=true){select.replaceChildren();if(includeAll){const opt=new Option('전체 단원','all');select.add(opt)}CHAPTERS.forEach(ch=>select.add(new Option(ch,ch)))}
function summary(){let count=0,correct=0,wrong=0,mastered=0;for(const r of Object.values(data.progress)){count+=r.seen||0;correct+=r.correct||0;if(r.lastCorrect===false)wrong++;if(r.lastCorrect===true)mastered++}return {count,correct,wrong,mastered}}
function renderStats(target){const s=summary();const items=[['전체 / 검증 완료',String(BANK.length)+' / '+QuizTrust.verifiedCount(BANK,'wireless'),'문항'],['풀이 횟수',s.count,'회'],['누적 정답률',rate(s.correct,s.count),'%'],['복습할 오답',s.wrong,'문항']];$(target).replaceChildren(...items.map(([label,value,suffix])=>{const c=el('div','stat');c.append(el('div','label',label));const v=el('div','value',String(value));v.append(el('span','suffix',suffix));c.append(v);return c}))}
const CHAPTER_COMPOSITION=[{"chapter":"Ch1 신호·시스템","categories":["신호와 시스템"],"original":60,"total":78},{"chapter":"Ch2 음성 디지털 부호화","categories":["디지털화와 다중화"],"original":57,"total":72},{"chapter":"Ch3 아날로그 변조","categories":["아날로그 변조"],"original":68,"total":85},{"chapter":"Ch4 디지털 변조","categories":["디지털 전송"],"original":71,"total":89},{"chapter":"Ch5 안테나 이론","categories":["전자파와 주파수 분류","전자파와 안테나 이론","안테나 파라미터"],"original":63,"total":144},{"chapter":"Ch6 안테나 실제","categories":["안테나 종류"],"original":15,"total":60},{"chapter":"Ch7 급전선 이론","categories":["급전선·도파관"],"original":30,"total":75},{"chapter":"Ch8 전파 전파 이론","categories":["전파 전파이론","페이딩·전리층"],"original":46,"total":131},{"chapter":"Ch9 고정통신 시스템","categories":["무선통신 시스템"],"original":45,"total":107},{"chapter":"Ch10 이동통신 시스템","categories":["이동통신 시스템"],"original":30,"total":75},{"chapter":"Ch11 위성통신 시스템","categories":["위성·레이더 시스템"],"original":15,"total":84}];
function renderComposition(){const cells=CHAPTER_COMPOSITION.map((x,i)=>{const qs=BANK.filter(q=>x.categories.includes(q.chapter)),n=qs.length,p=100*n/BANK.length,dist=['하','중','상'].map(l=>qs.filter(q=>q.difficulty===l).length);return '<tr><td>'+x.chapter+'</td><td>'+x.original+'</td><td>+'+(n-x.original)+'</td><td>'+n+'</td><td>'+dist.join('/')+'</td><td>'+p.toFixed(1)+'%</td><td><button class="composition-start" type="button" data-unit="'+i+'">선택 난이도 풀기</button></td></tr>';}).join('');
 $('compositionRows').innerHTML='<table class="composition-table"><thead><tr><th>단원</th><th>최초</th><th>추가</th><th>최종</th><th>하/중/상</th><th>비율</th><th>학습</th></tr></thead><tbody>'+cells+'<tr class="composition-total"><td>전체</td><td>500</td><td>+'+(BANK.length-500)+'</td><td>'+BANK.length+'</td><td>—</td><td>100%</td><td>—</td></tr></tbody></table><p class="mini">난이도를 선택하고 각 단원의 버튼을 누르면 해당 조건의 문제 전체를 풉니다.</p>';
 document.querySelectorAll('#compositionRows [data-unit]').forEach(b=>b.addEventListener('click',()=>startCompositionUnit(Number(b.dataset.unit))));
}
const COMPOSITION_CATEGORIES=[["신호와 시스템"],["디지털화와 다중화"],["아날로그 변조"],["디지털 전송"],["전자파와 주파수 분류","전자파와 안테나 이론","안테나 파라미터"],["안테나 종류"],["급전선·도파관"],["전파 전파이론","페이딩·전리층"],["무선통신 시스템"],["이동통신 시스템"],["위성·레이더 시스템"]];
function startCompositionUnit(index){
 const cats=COMPOSITION_CATEGORIES[index];
 if(!cats)return;
 const ids=BANK.filter(q=>cats.includes(q.chapter)&&($('difficultySelect').value==='all'||q.difficulty===$('difficultySelect').value)).map(q=>q.id);
 if(ids.length)begin('normal',ids);
}
function maybeStartLinkedUnit(){
 const params=new URLSearchParams(window.location.search);const sourceKind=params.get('kind');if(['코레일 기출','코레일 기출 응용','국가직 기출 응용','지방직 기출 응용','무선 설비 기사 필기 기출'].includes(sourceKind)){$('kindSelect').value=sourceKind;$('bankKind').value=sourceKind;renderHome();}const level=params.get('level');if(['하','중','상'].includes(level)){$('difficultySelect').value=level;$('compositionDifficulty').value=level;renderHome();}const raw=params.get('unit');
 if(raw!==null&&/^\d{1,2}$/.test(raw)){
  const n=Number(raw);
  if(n>=0&&n<COMPOSITION_CATEGORIES.length)startCompositionUnit(n);
 }
}
let showRepeated=false;
function renderHome(){StudyUI.refreshHome('wireless');renderStats('topStats');const eligible=BANK.filter(q=>QuizTrust.eligible(q,'wireless')&&($('chapterSelect').value==='all'||q.chapter===$('chapterSelect').value)&&($('kindSelect').value==='all'||q.kind===$('kindSelect').value)&&($('difficultySelect').value==='all'||q.difficulty===$('difficultySelect').value));const available=showRepeated?eligible:QuizQuality.dedupe(eligible);$('availableText').textContent=`현재 조건: ${available.length}문항${showRepeated?'':' (중복 제외)'} / 전체 등록 ${BANK.length}건`;const host=$('chapters');host.replaceChildren();for(const ch of CHAPTERS){const qs=BANK.filter(q=>q.chapter===ch);const attempted=qs.filter(q=>data.progress[q.id]?.seen).length;const b=el('button','chapter');const title=el('strong','',ch);const count=el('small','',`${qs.length}문항 · 학습 ${attempted}문항`);const track=el('span','meter');const progress=el('i');progress.style.width=rate(attempted,qs.length)+'%';track.append(progress);b.append(title,count,track);b.addEventListener('click',()=>{$('chapterSelect').value=ch;window.scrollTo({top:0,behavior:'smooth'});$('startBtn').focus();renderHome()});host.append(b)}}
function begin(type='normal',forcedIds=null){let qs;
 if(forcedIds)qs=forcedIds.map(id=>BANK.find(q=>q.id===id)).filter(Boolean);
 else if(type==='wrong')qs=BANK.filter(q=>data.progress[q.id]?.lastCorrect===false);
 else if(type==='fav')qs=BANK.filter(q=>data.bookmarks.includes(q.id));
 else qs=BANK.filter(q=>($('chapterSelect').value==='all'||q.chapter===$('chapterSelect').value)&&($('kindSelect').value==='all'||q.kind===$('kindSelect').value));
 if(!forcedIds&&$('difficultySelect').value!=='all')qs=qs.filter(q=>q.difficulty===$('difficultySelect').value);
 if(type==='normal'&&!showRepeated)qs=QuizQuality.dedupe(qs);
 qs=qs.filter(q=>QuizTrust.eligible(q,'wireless'));if(!qs.length){toast(type==='wrong'?'아직 복습할 오답이 없습니다.':type==='fav'?'즐겨찾기 문제를 먼저 지정하세요.':'선택한 조건에 맞는 문제가 없습니다.');return}
 const ordered=($('orderSelect').value==='sequential' && type==='normal' && !forcedIds)?[...qs].sort((a,b)=>a.page-b.page || a.id.localeCompare(b.id)):shuffle(qs);
 const n=$('countSelect').value==='all'?ordered.length:Math.min(parseInt($('countSelect').value,10),ordered.length);
 const actual=forcedIds?ordered:ordered.slice(0,n);lastSessionConfig={type,chapter:$('chapterSelect').value,kind:$('kindSelect').value,count:$('countSelect').value,order:$('orderSelect').value};
 session={ids:actual.map(q=>q.id),index:0,answers:{},correct:0,answered:0,skipped:0,type};view('quiz');renderQuestion()}
function currentQuestion(){return BANK.find(q=>q.id===session.ids[session.index])}
function renderQuestion(){const q=currentQuestion();QuizTrust.validateMath(q);const selected=session.answers[q.id];if(!session.questionStartTimes)session.questionStartTimes={};if(selected===undefined&&!session.questionStartTimes[q.id])session.questionStartTimes[q.id]=Date.now();$('quizPosition').textContent=`${session.index+1} / ${session.ids.length}`;$('quizMeta').textContent=session.type==='wrong'?'오답 복습':session.type==='fav'?'즐겨찾기 복습':q.kind+' 문제';$('quizProgress').style.width=(session.index/session.ids.length*100)+'%';$('qChapter').textContent=q.chapter;$('qMeta').textContent=`${q.id} · ${q.difficulty} 난이도 · ${q.topic} · ${q.sourceLabel?(q.sourceQuestion?`${q.sourceLabel} · 참고 문항 ${q.sourceQuestion}번 · 출처 PDF ${q.sourcePage}쪽`:`${q.sourceLabel} · 공개 기출의 전공 범위 참고 · 신규 응용문항`):`PDF ${q.sourcePages?.join(', ')||q.page}쪽`}`;const examMatch=/^RCE(\d{4})(\d{2})(\d{2})Q(\d{3})$/.exec(q.id);const examBadge=$('examDateBadge');examBadge.hidden=!examMatch;examBadge.textContent=examMatch?`무선설비기사 · ${examMatch[1]}년 ${Number(examMatch[2])}월 ${Number(examMatch[3])}일 기출 · ${Number(examMatch[4])}번`:'';$('qQuestion').textContent=q.question;$('qMeta').append(QuizTrust.statusTag(q,'wireless'));window.TelecomCrowdStats?.render('wireless',q);$('qualityBox').replaceChildren(QuizQuality.panel(q,'wireless'));StudyUI.renderMemo(q,'wireless');const isFav=data.bookmarks.includes(q.id);$('bookmarkBtn').textContent=isFav?'★ 저장됨':'☆ 즐겨찾기';$('bookmarkBtn').onclick=()=>{if(data.bookmarks.includes(q.id))data.bookmarks=data.bookmarks.filter(id=>id!==q.id);else data.bookmarks.push(q.id);save();StudyStore.setBookmark('wireless',q.id,data.bookmarks.includes(q.id));$('bookmarkBtn').textContent=data.bookmarks.includes(q.id)?'★ 저장됨':'☆ 즐겨찾기'};
 $('answers').replaceChildren(...q.options.map((opt,i)=>{const b=el('button','choice');const bubble=el('span','bubble',String(i+1));b.append(bubble,el('span','',opt));b.addEventListener('click',()=>answer(i));if(selected!==undefined){b.disabled=true;if(QuizTrust.gradeable(q,'wireless')&&i===q.answer)b.classList.add('correct');else if(QuizTrust.gradeable(q,'wireless')&&i===selected)b.classList.add('wrong')}return b}));
 const feedback=$('feedback');if(selected!==undefined){feedback.hidden=false;feedback.className='explanation'+(QuizTrust.gradeable(q,'wireless')&&selected!==q.answer?' bad':'');feedback.replaceChildren(el('h3','',!QuizTrust.gradeable(q,'wireless')?'채점 보류 · 원문·수식·정답을 확인 중입니다.':selected===q.answer?'정답입니다.':'오답입니다. 정답은 '+(q.answer+1)+'번입니다.'),el('p','',q.explanation));const a=el(q.sourceLabel?'span':'a','',q.sourceLabel?`${q.sourceLabel} · ${q.sourceQuestion}번 · 첨부 PDF ${q.sourcePage}쪽`:`기존 PDF ${q.page}쪽 열기 ↗`);if(!q.sourceLabel){a.href='무선공학.pdf#page='+q.page;a.target='_blank';a.rel='noopener'};a.style.fontSize='12px';a.style.display='inline-block';a.style.marginTop='10px';feedback.append(a)}else{feedback.hidden=true;feedback.replaceChildren()}
 $('nextBtn').hidden=selected===undefined;$('nextBtn').textContent=session.index===session.ids.length-1?'결과 보기 →':'다음 문제 →';$('skipBtn').hidden=selected!==undefined;QuizTrust.renderMath(q,[$('qQuestion'),$('answers'),$('feedback')]);}
function answer(index){const q=currentQuestion();if(session.answers[q.id]!==undefined)return;session.answers[q.id]=index;session.answered++;const graded=QuizTrust.gradeable(q,'wireless');const correct=graded&&index===q.answer;if(correct)session.correct++;let r=data.progress[q.id]||{seen:0,correct:0,wrong:0};r.seen++;if(graded){if(correct)r.correct++;else r.wrong++;}r.lastCorrect=graded?correct:null;r.lastAt=Date.now();data.progress[q.id]=r;save();StudyStore.record('wireless',q,{correct,graded,durationMs:Date.now()-(session.questionStartTimes?.[q.id]||Date.now())});StudyUI.refreshHome('wireless');window.TelecomCrowdStats?.record('wireless',q,correct,graded);renderQuestion()}
function advance(){if(!session)return;if(session.index+1>=session.ids.length){finish();return}session.index++;renderQuestion();window.scrollTo({top:0,behavior:'smooth'})}
function skip(){const q=currentQuestion();if(session.answers[q.id]===undefined)session.skipped++;advance()}
function finish(){if(!session)return;lastSessionIds=[...session.ids];const total=session.ids.length;const wrongIDs=session.ids.filter(id=>session.answers[id]!==undefined&&QuizTrust.gradeable(BANK.find(q=>q.id===id),'wireless')&&session.answers[id]!==BANK.find(q=>q.id===id).answer);const correct=session.correct;const answered=session.answered;const gradedCount=session.ids.filter(id=>session.answers[id]!==undefined&&QuizTrust.gradeable(BANK.find(q=>q.id===id),'wireless')).length;const pending=answered-gradedCount;data.history.unshift({date:new Date().toISOString(),total,answered,correct,chapter:session.type==='normal'?lastSessionConfig.chapter:session.type});data.history=data.history.slice(0,25);save();StudyStore.addSession('wireless',{kind:session.type,questionCount:total,answered,gradedCount,correct,skipped:total-answered});const used=session;session=null;view('result');$('bigScore').textContent=rate(correct,gradedCount)+'%';$('resultLabel').textContent=`${gradedCount}문항 채점 중 ${correct}문항 정답 · 채점 보류 ${pending}개 · 건너뛴 문제 ${total-answered}개`;$('resultStats').replaceChildren(...[['정답',correct],['오답',gradedCount-correct],['채점 보류',pending],['미응답',total-answered]].map(([t,n])=>{const d=el('div');d.append(el('b','',String(n)),el('span','mini',t));return d}));$('retryWrong').disabled=wrongIDs.length===0;$('retryWrong').onclick=()=>begin('wrong',wrongIDs);$('resultList').replaceChildren(...used.ids.map((id,i)=>{const q=BANK.find(z=>z.id===id);const a=used.answers[id];const label=a===undefined?'건너뜀':!QuizTrust.gradeable(q,'wireless')?'채점 보류':a===q.answer?'정답':'오답';const r=el('div','listrow');const txt=el('div');txt.append(el('b','',`${i+1}. ${q.question.replace(/\n/g,' ').slice(0,84)}`),el('div','mini',`${q.chapter} · ${q.sourceLabel?`${q.sourceLabel} · ${q.sourceQuestion}번`:`PDF ${q.page}쪽`}`));const badge=el('span','pill',label);if(label==='오답')badge.style.color='var(--danger)';if(label==='정답')badge.style.color='var(--success)';r.append(txt,badge);return r}))}
function renderBank(){const keyword=$('bankSearch').value.trim().toLocaleLowerCase();const ch=$('bankChapter').value;const kind=$('bankKind').value;const difficulty=$('bankDifficulty').value;const raw=BANK.filter(q=>QuizTrust.eligible(q,'wireless')&&(difficulty==='all'||q.difficulty===difficulty)&&(ch==='all'||q.chapter===ch)&&(kind==='all'||q.kind===kind)&&(keyword===''||[q.question,q.explanation,q.topic,q.id,q.sourceLabel||'',...q.options].join(' ').toLocaleLowerCase().includes(keyword)));const arr=showRepeated?raw:QuizQuality.dedupe(raw);const PAGE_SIZE=25, pages=Math.max(1,Math.ceil(arr.length/PAGE_SIZE));bankPage=Math.max(0,Math.min(bankPage,pages-1));$('bankCount').textContent=`검색 결과 ${arr.length}문항${showRepeated?'':' (중복 제외)'} / 전체 등록 ${BANK.length}건 · 페이지 ${bankPage+1}/${pages}`;$('bankList').replaceChildren(...arr.slice(bankPage*PAGE_SIZE,(bankPage+1)*PAGE_SIZE).map(q=>{const wrap=el('div');const b=el('button','bankrow');b.append(el('div','bmeta',`${q.id} · ${q.chapter} · ${q.kind} · ${q.difficulty} · ${q.sourceLabel?`${q.sourceLabel} · ${q.sourceQuestion}번 · 첨부 PDF ${q.sourcePage}쪽`:`PDF ${q.page}쪽`}`),el('div','btitle',q.question.replace(/\n/g,' ')));wrap.append(b);const box=el('div','bankdetail');box.hidden=bankOpened!==q.id;box.append(QuizQuality.panel(q,'wireless'));box.append(el('p','',q.question));q.options.forEach((op,i)=>box.append(el('div','opt'+(QuizTrust.gradeable(q,'wireless')&&i===q.answer?' good':''),`${i+1}. ${op} ${QuizTrust.gradeable(q,'wireless')&&i===q.answer?'✓ 정답':''}`)));box.append(el('p','',q.explanation));b.addEventListener('click',()=>{bankOpened=bankOpened===q.id?null:q.id;box.hidden=bankOpened!==q.id});wrap.append(box);return wrap}));const pager=$('bankPager');pager.replaceChildren();const prev=el('button','btn','← 이전');prev.disabled=bankPage===0;prev.onclick=()=>{bankPage--;renderBank();window.scrollTo(0,0)};const next=el('button','btn','다음 →');next.disabled=bankPage===pages-1;next.onclick=()=>{bankPage++;renderBank();window.scrollTo(0,0)};pager.append(prev,el('span','mini',`${bankPage+1} / ${pages}`),next)}
function renderRecords(){renderStats('recordStats');$('chapterRecords').replaceChildren(...CHAPTERS.map(ch=>{const qs=BANK.filter(q=>q.chapter===ch);let seen=0,correct=0;for(const q of qs){const r=data.progress[q.id];if(r){seen+=r.seen||0;correct+=r.correct||0}}const d=el('div','listrow');d.append(el('div','',ch),el('div','mini',`${rate(correct,seen)}% · ${seen}회 풀이`));return d}));$('historyList').replaceChildren(...(data.history.length?data.history.slice(0,9).map(h=>{const d=el('div','listrow');d.append(el('span','mini',new Date(h.date).toLocaleString('ko-KR')),el('b','',`${h.correct}/${h.answered} 정답`));return d}):[el('p','muted','아직 학습 기록이 없습니다.')]))}
function safeQuit(){if(session && session.answered>0 && !confirm('현재 학습을 종료하고 홈으로 돌아가시겠습니까? 응답 기록은 다음 접속에도 유지됩니다.'))return false;session=null;view('home');return true}
function init(){StudyUI.mount('wireless',{bank:BANK,legacyKey:PREF_STORE,legacyData:()=>({progress:data.progress,bookmarks:data.bookmarks,history:data.history,theme:data.theme}),openAnalytics:()=>view('analytics'),beginDue:ids=>begin('normal',ids)});QuizSource.register(BANK,'wireless');QuizTrust.attach(BANK,'wireless',{onChange:()=>{renderHome();if(currentView==='bank')renderBank()}});QuizTrust.loadOverrides(()=>{renderHome();if(currentView==='bank')renderBank()});renderComposition();$('compositionBtn').addEventListener('click',()=>{const panel=$('compositionPanel'),btn=$('compositionBtn');panel.hidden=!panel.hidden;btn.setAttribute('aria-expanded',String(!panel.hidden));btn.textContent=panel.hidden?'▤ 전체 문제 구성 보기':'▴ 전체 문제 구성 접기';});chaptersSelect($('chapterSelect'));chaptersSelect($('bankChapter'));$('chapterSelect').addEventListener('change',renderHome);$('difficultySelect').addEventListener('change',()=>{$('compositionDifficulty').value=$('difficultySelect').value;renderHome();});$('compositionDifficulty').addEventListener('change',()=>{$('difficultySelect').value=$('compositionDifficulty').value;renderHome();});$('kindSelect').addEventListener('change',renderHome);$('startBtn').addEventListener('click',()=>begin());$('wrongBtn').addEventListener('click',()=>begin('wrong'));$('favBtn').addEventListener('click',()=>begin('fav'));$('quitBtn').addEventListener('click',safeQuit);$('nextBtn').addEventListener('click',advance);$('skipBtn').addEventListener('click',skip);$('resultHome').addEventListener('click',()=>view('home'));$('repeatSession').addEventListener('click',()=>begin('normal',lastSessionIds));document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>{if(session&&currentView==='quiz'&&!safeQuit())return;view(b.dataset.nav)}));$('bankSearch').addEventListener('input',()=>{bankPage=0;renderBank()});$('bankChapter').addEventListener('change',()=>{bankPage=0;renderBank()});$('bankKind').addEventListener('change',()=>{bankPage=0;renderBank()});$('bankDifficulty').addEventListener('change',()=>{bankPage=0;renderBank()});$('exportBtn').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({version:1,...data},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='무선공학1000_학습기록_'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});$('importBtn').addEventListener('click',()=>$('importFile').click());$('importFile').addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;try{const parsed=JSON.parse(await file.text());if(typeof parsed.progress!=='object'||!Array.isArray(parsed.bookmarks)||!Array.isArray(parsed.history))throw Error('형식');if(!confirm('기존 학습 기록을 백업 파일 기록으로 교체할까요?'))return;data.progress=parsed.progress;data.bookmarks=parsed.bookmarks;data.history=parsed.history;save();renderRecords();toast('학습 기록을 복원했습니다.')}catch{toast('올바른 학습 기록 파일이 아닙니다.')}finally{ev.target.value=''}});$('resetBtn').addEventListener('click',()=>{if(!confirm('모든 풀이·오답·즐겨찾기 기록을 초기화할까요?'))return;data.progress={};data.bookmarks=[];data.history=[];save();renderRecords();toast('학습 기록을 초기화했습니다.')});$('themeBtn').addEventListener('click',()=>{data.theme=data.theme==='dark'?'light':'dark';theme();save()});document.addEventListener('keydown',e=>{if(currentView!=='quiz'||!session||e.altKey||e.ctrlKey||e.metaKey)return;if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;const a=session.answers[currentQuestion().id];if(a===undefined&&['1','2','3','4','5'].includes(e.key)&&Number(e.key)<=currentQuestion().options.length){answer(parseInt(e.key,10)-1)}else if(a!==undefined&&['Enter','ArrowRight'].includes(e.key)){e.preventDefault();advance()}});theme();renderHome();}
function theme(){document.documentElement.dataset.theme=data.theme;$('themeBtn').textContent=data.theme==='dark'?'☀':'☾'}

for(const id of ['showRepeatsHome','showRepeatsBank'])$(id).addEventListener('change',e=>{showRepeated=e.target.checked;$('showRepeatsHome').checked=showRepeated;$('showRepeatsBank').checked=showRepeated;bankPage=0;renderHome();if(currentView==='bank')renderBank()});
